tape( 'the function returns a pseudorandom number generator (no options)', function test( t ) {
	var xorshift32;
	var v;
	var i;

	xorshift32 = factory();
	for ( i = 0; i < 1000; i++ ) {
		v = xorshift32();
		t.strictEqual( typeof v, 'number', 'returns expected value' );
		t.strictEqual( isNonNegativeInteger(v), true, 'returns a non-negative-integer' );
		t.strictEqual( v >= 0 && v <= UINT32_MAX, true, 'value is in valid range' );
	}
	t.end();
});

tape( 'the function returns a pseudorandom number generator (options; no seed)', function test( t ) {
	var xorshift32;
	var v;
	var i;

	xorshift32 = factory( {} );
	for ( i = 0; i < 1000; i++ ) {
		v = xorshift32();
		t.strictEqual( typeof v, 'number', 'returns expected value' );
		t.strictEqual( isNonNegativeInteger(v), true, 'returns a non-negative integer' );
		t.strictEqual( v >= 0 && v <= UINT32_MAX, true, 'value is in valid range' );
	}
	t.end();
});

tape( 'the function returns a seeded pseudorandom number generator (integer seed)', function test( t ) {
	var xorshift32a;
	var xorshift32b;
	var seed;
	var v1;
	var v2;
	var i;

	seed = 12345;

	xorshift32a = factory({
		'seed': seed
	});
	xorshift32b = factory({
		'seed': seed
	});

	t.notEqual( xorshift32a, xorshift32b, 'separate generators' );

	for ( i = 0; i < 1e3; i++ ) {
		v1 = xorshift32a();
		v2 = xorshift32b();
		t.strictEqual( v1, v2, 'both return same number' );
	}
	t.end();
});

