tape( 'the function supports specifying the generator state', function test( t ) {
	var state;
	var rng;
	var arr;
	var i;

	rng = factory({
		'seed': 54321
	});

	// Move to a future state...
	for ( i = 0; i < 100; i++ ) {
		rng();
	}
	// Capture the current state:
	state = rng.state;

	// Move to a future state...
	arr = [];
	for ( i = 0; i < 100; i++ ) {
		arr.push( rng() );
	}

	// Create another PRNG using the captured state:
	rng = factory({
		'state': state
	});

	// Replay previously generated values...
	for ( i = 0; i < 100; i++ ) {
		t.strictEqual( rng(), arr[ i ], 'returns expected value at iteration '+i );
	}
	t.end();
});

